function div_noty(e) {
    $.noty.consumeAlert({
        layout: "top",
        type: e.tipo,
        dismissQueue: !0,
        timeout: 1750
    }), alert(e.texto)
}

function ObtieneAPIKey() {
    let e = "";
    return params = {
        Empresa_Id: 3,
        Usuario_Id: 1
    }, $.ajax({
        async: !1,
        data: JSON.stringify(params),
        type: "POST",
        dataType: "json",
        url: `${sessionStorage.pathWs}/api/General/ObtieneApikey`,
        headers: {
            "Content-Type": "application/json;  charset=utf-8"
        },
        beforeSend: function (e) {},
        success: function (t) {
            "" == t.Table[0].ApiKey && "-1" == t.Table[0].ApiKey || (e = t.Table[0].ApiKey)
        },
        error: function (t, n, o) {
            console.log("Error ObtieneAPIKey =>", t.responseText), e = ""
        }
    }), e
}

