function generateToken() {
    const min = 10;
	const max = 20;
	const longitud = Math.floor(Math.random() * (max - min)) + min;
    var chars = '#@abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_';
    var token = '';
    for(var i = 0; i < longitud; i++) {
        token += chars[Math.floor(Math.random() * chars.length)];
    }
    return token;
}

function selectElement(e, t) {
    document.getElementById(e).value = t
}

function CheckSession() {
    const e = sessionStorage.getItem("_TOKEN"),
        t = new Date / 1e3 | 0;
    e ? $.ajax({
        headers: { 
            'Accept': 'application/json',
            'Content-Type': 'application/json' 
          },
        data: JSON.stringify({
            Token: e,
            Key: t
        }) ,
        type: "post",
        dataType: "json",
        url: `${sessionStorage.pathWs}/api/Portal/GetSesion`,
        beforeSend: function (e) {},
        success: function (e) {            
            if (e.Respuesta.length <= 0){
                window.location="index.html";
                DesconectarAgenteAdmin() 
            }          
        },
        error: function (e) {
            console.log("Error =>", e)
        }
    }) : (console.log("Redirección"), window.location = "index.html")
}

function ObtieneRaiz(e) {
    return url_ = e + "/api/General/ObtieneDriveRaiz", resultDrive = {
        Parent: "",
        ParentDev: ""
    }, $.ajax({
        async: !1,
        url: url_,
        type: "POsT",
        beforeSend: function (e) {
            $("html, body").animate({
                scrollTop: 0
            }, "slow")
        },
        success: function (e) {
            for (i in e.Table) resultDrive.Parent = e.Table[i].IdDrive, resultDrive.ParentDev = e.Table[i].IdDriveDev
        },
        error: function (e, t, n) {
            console.log("Error: " + e + "\n" + t + "\n" + n), div_noty({
                tipo: "warning",
                texto: "Falla en comunicación"
            })
        }
    }), resultDrive
}

function encodeBase64(e) {
    if ("function" == typeof btoa) return btoa(e);
    if ("function" == typeof Buffer) return Buffer.from(e, "utf-8").toString("base64");
    throw new Error("Failed to determine the platform specific encoder")
}

function decodeBase64(e) {
    if ("function" == typeof atob) return atob(e);
    if ("function" == typeof Buffer) return Buffer.from(e, "base64").toString("utf-8");
    throw new Error("Failed to determine the platform specific decoder")
}

function cadena() {
    let e = "";
    return $.ajax({
        async: !1,
        type: "GET",
        url: "assets/include/rpa_k.json",
        dataType: "json",
        contentType: "application/json; charset=UTF-8",
        beforeSend: function (e) {},
        success: function (t) {
            if (string = t.string, "function" == typeof atob) return e = atob(string);
            if ("function" == typeof Buffer) return e = Buffer.from(string, "base64").toString("utf-8");
            throw new Error("Falla al obtener string")
        },
        error: function (e, t) {}
    }), e
}

function validar() {
    let e = 0;
    const t = window.location.pathname,
        n = JSON.parse(sessionStorage.getItem("listaMenu"));
    for (var o in n)
        if (t.search(n[o][0]) > 0) {
            e = 1;
            break
        } return 0 == e && (window.location.href = "login.html"), e
}
function getFormData($form){
    var unindexed_array = $form.serializeArray();
    var indexed_array = {};
  
    $.map(unindexed_array, function(n, i){
        indexed_array[n['name']] = n['value'];
    });
  
    return indexed_array;
  }

  function getArrayData(data = {}){
    var indexed_array = {};
  
    $.map(data, function(n, i){
        indexed_array[n['name']] = n['value'];
    });
  
    return indexed_array;
  }

